OverworldSprites.has = function (species) { return !!this.species[species]; };
OverworldSprites.frame = function (species, o) {
  const e = this.species[species]; if (!e) return null; o = o || {};
  const d = Math.max(0, this.dirs.indexOf(o.dir || 'down')), st = (o.step | 0) & 1;
  return { x: e.x + (o.shiny && e.shiny ? 2 * e.w : 0) + st * e.w, y: e.y + d * e.h, w: e.w, h: e.h };
};

if (typeof window !== 'undefined') window.OverworldSprites = OverworldSprites;
